# Exhaustive search for n=4 sequences
results = []
failures = []

X1_range = range(1, 6)
X2_range = range(1, 11)

for x1 in X1_range:
    for x2 in X2_range:
        # --- Step 1: Calculate x3 ---
        # (x3 + 1)(x1 + 1) = x2^2 + 1
        numerator_x3 = x2**2 + 1
        denominator_x3 = x1 + 1

        if numerator_x3 % denominator_x3 == 0:
            x3_plus_1 = numerator_x3 // denominator_x3
            x3 = x3_plus_1 - 1

            if x3 > 0:
                # --- Step 2: Calculate x4 ---
                # (x4 + 1)(x2 + 1) = x3^2 + 1
                numerator_x4 = x3**2 + 1
                denominator_x4 = x2 + 1

                if numerator_x4 % denominator_x4 == 0:
                    x4_plus_1 = numerator_x4 // denominator_x4
                    x4 = x4_plus_1 - 1

                    if x4 > 0:
                        # Success!
                        results.append((x1, x2, x3, x4))
                    else:
                        # Failed because x4 <= 0
                        failures.append((x1, x2, x3, "x4 <= 0"))
                else:
                    # Failed because x4 is not an integer
                    failures.append((x1, x2, x3, "x4 not integer"))
        else:
            # Failed because x3 is not an integer
            failures.append((x1, x2, "N/A", "x3 not integer"))

print("--- Successful Sequences (n=4) ---")
if results:
    for seq in results:
        print(f"Sequence: {seq}")
else:
    print("No successful sequences found.")

print("\n--- Failure Summaries ---")
if failures:
    # Only printing the count for brevity in the tool output, but all data is in memory for me.
    print(f"Total failures analyzed: {len(failures)}")
    # Printing the first 5 failures for concrete documentation
    for i, fail in enumerate(failures[:5]):
        print(f"Failure {i+1}: (x1={fail[0]}, x2={fail[1]}, x3={fail[2]}, Reason: {fail[3]})")
else:
    print("No failures recorded (this implies all 50 pairs succeeded, which is unlikely).")
